<?php
require_once '../../config.php';require_once __DIR__.'/Language.php';require_once __DIR__.'/Compatibility.php';
$challenge=WbceAuthFactorManager::current();$provider=WbceAuthFactorManager::currentProvider();if(!$challenge||!$provider||empty($_SESSION['USER_ID'])||(int)$_SESSION['USER_ID']!==(int)$challenge['user_id']){WbceAuthFactorManager::cancel();header('Location: '.ADMIN_URL.'/login/');exit;}
global $database;$result=$database->query('SELECT * FROM `{TP}users` WHERE `user_id`='.(int)$challenge['user_id'].' AND `active`=1');$user=$result?$result->fetchRow(MYSQLI_ASSOC):null;if(!$user){WbceAuthFactorManager::cancel();header('Location: '.ADMIN_URL.'/logout/');exit;}
$error='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$nonce=(string)($_POST['auth_nonce']??'');if(!hash_equals((string)$challenge['nonce'],$nonce)){$error=wbce_two_factor_t('security_expired');}elseif($provider->verify($user,$_POST)){wbce_do_action('auth.challenge.passed',$provider->getId(),(int)$user['user_id']);if(WbceAuthFactorManager::advance()){$completed=WbceAuthFactorManager::consume();if(method_exists('WbceAuthFactorManager','markVerified'))WbceAuthFactorManager::markVerified((int)$user['user_id']);$target=wbce_apply_filters('auth.login.redirect',$completed['return_url'],$user);header('Location: '.wbce_safe_redirect_url($target,ADMIN_URL.'/start/'));exit;}header('Location: '.WB_URL.'/modules/two_factor/factor.php');exit;}else{$error=wbce_two_factor_t('factor_invalid');wbce_do_action('auth.challenge.failed',$provider->getId(),(int)$user['user_id']);if(WbceAuthFactorManager::recordFailure()){header('Location: '.ADMIN_URL.'/logout/');exit;}}}
$theme=defined('DEFAULT_THEME')?preg_replace('/[^a-zA-Z0-9_-]/','',(string)DEFAULT_THEME):'';$styles=array('css/login.css','css/theme.css','css/style.min.css','css/style.css');header('Content-Type: text/html; charset=UTF-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');header('X-Frame-Options: SAMEORIGIN');header("Content-Security-Policy: frame-ancestors 'self'");header('Referrer-Policy: same-origin');
?><!doctype html><html lang="<?=htmlspecialchars(strtolower(substr(defined('LANGUAGE')?LANGUAGE:'en',0,2)),ENT_QUOTES,'UTF-8')?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars(wbce_two_factor_t('admin_title'),ENT_QUOTES,'UTF-8')?></title><?php foreach($styles as $style):if($theme!==''&&is_file(WB_PATH.'/templates/'.$theme.'/'.$style)):?><link rel="stylesheet" href="<?=htmlspecialchars(WB_URL.'/templates/'.$theme.'/'.$style,ENT_QUOTES,'UTF-8')?>"><?php endif;endforeach;?><link rel="stylesheet" href="<?=htmlspecialchars(WB_URL.'/modules/two_factor/factor.css',ENT_QUOTES,'UTF-8')?>"></head><body class="wbce-auth-page"><main class="wbce-auth-card wbce-admin-card"><?=$provider->renderChallenge($user,$error)?><input type="hidden" form="wbce-auth-factor" name="auth_nonce" value="<?=htmlspecialchars($challenge['nonce'],ENT_QUOTES,'UTF-8')?>"></main></body></html>
